let[@axiom] tree_positive_depth_is_not_leaf = fun (l : (int tree)) -> fun (n : int) -> (((depth l n) && (n > 0)) #==> (not (leaf l)))
let[@axiom] tree_no_leaf_exists_lch = fun (l : (int tree)) -> fun ((l1 [@ex]) : (int tree)) -> ((not (leaf l)) #==> (lch l l1))
let[@axiom] tree_no_leaf_exists_rch = fun (l : (int tree)) -> fun ((l1 [@ex]) : (int tree)) -> ((not (leaf l)) #==> (rch l l1))
let[@axiom] tree_no_leaf_exists_root = fun (l : (int tree)) -> fun ((x [@ex]) : int) -> ((not (leaf l)) #==> (root l x))
let[@axiom] tree_depth_geq_0 = fun (l : (int tree)) (n : int) -> ((depth l n) #==> (n >= 0))
let[@axiom] tree_depth_0_is_leaf = fun (l : (int tree)) (n : int) -> (((depth l n) && (n == 0)) #==> (leaf l))
let[@axiom] tree_depth_exists = fun (l : (int tree)) -> fun ((n [@ex]) : int) -> (depth l n)
let[@axiom] tree_depth_unique = fun (l : (int tree)) -> fun (n : int) -> fun (m : int) -> (((depth l n) && (depth l m)) #==> (n == m))
let[@axiom] tree_depth_node = fun (l : (int tree)) -> fun (l1 : (int tree)) -> fun (l2 : (int tree)) -> fun (n1 : int) -> fun (n2 : int) -> (((depth l1 n1) && ((depth l2 n2) && ((lch l l1) && (rch l l2)))) #==> (((n1 > n2) #==> (depth l (n1 + 1))) && ((n2 >= n1) #==> (depth l (n2 + 1)))))
let[@axiom] tree_lower_bound_destruct = fun (l : (int tree)) -> fun (l1 : (int tree)) -> fun (x : int) -> (((lower_bound l x) && ((lch l l1) && (not (leaf l1)))) #==> (lower_bound l1 x))
let[@axiom] tree_lower_bound_destruct_2 = fun (l : (int tree)) -> fun (l1 : (int tree)) -> fun (x : int) -> (((bst l) && ((root l x) && ((rch l l1) && (not (leaf l1))))) #==> (lower_bound l1 x))
let[@axiom] tree_upper_bound_destruct = fun (l : (int tree)) -> fun (l1 : (int tree)) -> fun (x : int) -> (((upper_bound l x) && ((rch l l1) && (not (leaf l1)))) #==> (upper_bound l1 x))
let[@axiom] tree_upper_bound_destruct_2 = fun (l : (int tree)) -> fun (l1 : (int tree)) -> fun (x : int) -> (((bst l) && ((root l x) && ((lch l l1) && (not (leaf l1))))) #==> (upper_bound l1 x))
let[@axiom] tree_bst_lch_bst = fun (l : (int tree)) (l1 : (int tree)) -> (((lch l l1) && (bst l)) #==> (bst l1))
let[@axiom] tree_bst_rch_bst = fun (l : (int tree)) (l1 : (int tree)) -> (((rch l l1) && (bst l)) #==> (bst l1))
